"""Glossary lookup for Self-Healing Polymer Networks."""

GLOSSARY = {
    "self-assembly": "components organizing into structures through their own interactions",
    "metamaterial": "an engineered structure with properties not found in its base materials",
    "nanocomposite": "a material combining nanoscale reinforcements with a matrix",
    "characterization": "the measurement techniques that reveal actual structure",
    "yield": "the fraction of production meeting specification",
    "functionalization": "adding chemical groups to give a surface new behavior",
}

def lookup(term):
    key = term.strip().lower()
    for k, v in GLOSSARY.items():
        if k.lower() == key:
            return k + ": " + v
    cands = [k for k in GLOSSARY if key in k.lower()]
    return ("Did you mean: " + ", ".join(cands)) if cands else "No entry."


if __name__ == "__main__":
    print("Self-Healing Polymer Networks glossary — %d terms" % len(GLOSSARY))
    for t in list(GLOSSARY)[:3]:
        print("-", lookup(t))

"""Piece model: Precursor Chemistry — part of the Self-Healing Polymer Networks system."""
import random

class SelfHealingPolymerNetworksPiece1PrecursorChemistry:
    """Models the Precursor Chemistry piece: specification check and behavior sample."""

    SPEC = {"piece": "Precursor Chemistry", "interfaces": 3, "redundancy": 2}

    def __init__(self, seed=11):
        self.rng = random.Random(seed)

    def spec_check(self):
        """Verify the piece meets its interface contract."""
        results = {}
        for i in range(self.SPEC["interfaces"]):
            # simulated conformance measurement around a nominal value
            measured = 1.0 + self.rng.uniform(-0.04, 0.04)
            results["interface_%d" % i] = round(measured, 3)
        ok = all(0.94 <= v <= 1.06 for v in results.values())
        return {"pass": ok, "measurements": results}

    def simulate(self, cycles=24):
        """Sample operating behavior over a number of cycles."""
        health = 1.0
        for _ in range(cycles):
            stress = self.rng.uniform(0.0, 0.06)
            health = max(0.0, health - stress * 0.2)
            health = min(1.0, health + 0.05)  # recovery / maintenance
        return {"cycles": cycles, "health": round(health, 3),
                "redundancy_ok": health > 0.5}


if __name__ == "__main__":
    m = SelfHealingPolymerNetworksPiece1PrecursorChemistry(seed=11)
    sc = m.spec_check()
    sm = m.simulate(24)
    print("Precursor Chemistry — Self-Healing Polymer Networks")
    print("spec check pass:", sc["pass"], "| measurements:", sc["measurements"])
    print("health after", sm["cycles"], "cycles:", sm["health"])

