"""Parameter optimization model — model for Self-Healing Polymer Networks.
Domain: nanotechnology and advanced materials. Deterministic demonstration model (seeded).
"""
import random

class SelfHealingPolymerNetworksSim:
    """Random-restart hill climbing over a design parameter space."""

    def __init__(self, seed=7):
        self.rng = random.Random(seed)

    @staticmethod
    def objective(x, y):
        # illustrative smooth landscape with one global optimum region
        return -((x - 3.0) ** 2 + 0.5 * (y + 1.0) ** 2) - 0.1 * abs(x * y)

    def hill_climb(self, start, steps=60):
        x, y = start
        best = self.objective(x, y)
        for _ in range(steps):
            nx = x + self.rng.uniform(-0.6, 0.6)
            ny = y + self.rng.uniform(-0.6, 0.6)
            val = self.objective(nx, ny)
            if val > best:
                x, y, best = nx, ny, val
        return (round(x, 3), round(y, 3), round(best, 3))

    def optimize(self, restarts=8):
        runs = [self.hill_climb((self.rng.uniform(-6, 6), self.rng.uniform(-6, 6)))
                for _ in range(restarts)]
        return max(runs, key=lambda r: r[2])


if __name__ == "__main__":
    opt = SelfHealingPolymerNetworksSim(seed=7)
    x, y, val = opt.optimize(restarts=8)
    print("Self-Healing Polymer Networks optimization model")
    print("best parameters: x =", x, "y =", y, "| objective:", val)
